get, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ELDRITCH_BONE_HAIRPIN) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ELDRITCH_BONE_HAIRPIN)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.ELDRITCH_BONE_HAIRPIN) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.ELDRITCH_BONE_HAIRPIN })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.MND, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/eldritch_horn_hairpin.lua"]={["Path"]="scripts/items/eldritch_horn_hairpin.lua",["SHA256"]="60c8ad7054a57ac71330ead68bda3546af7558d6a50768d8989795a31dd3a678",["Text"]="-----------------------------------\n-- ID: 15269\n-- Item: eldritch_horn_hairpin\n-- Item Effect: INT+3 MND+3\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ELDRITCH_HORN_HAIRPIN) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ELDRITCH_HORN_HAIRPIN)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.ELDRITCH_HORN_HAIRPIN) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.ELDRITCH_HORN_HAIRPIN })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.MND, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/elixir.lua"]={["Path"]="scripts/items/elixir.lua",["SHA256"]="e1be42ce6f167651bc3eb429b023a684a4c913a69cec8ed500faeb76f9c065b0",["Text"]="-----------------------------------\n-- ID: 4145\n-- Item: Elixir\n-- Item Effect: Instantly restores 25% of HP and MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    local mHP = target:getMaxHP()\n    local cHP = target:getHP()\n    local mMP = target:getMaxMP()\n    local cMP = target:getMP()\n\n    if mHP == cHP and mMP == cMP then\n        result = 56 -- Does not let player use item if their hp and mp are full\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    target:addHP((target:getMaxHP() / 100) * 25)\n    target:addMP((target:getMaxMP() / 100) * 25)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP_AND_MP)\nend\n\nreturn itemObject\n"},["scripts/items/elixir_tank.lua"]={["Path"]="scripts/items/elixir_tank.lua",["SHA256"]="37cf71b878d0446fdb528c2cdb55f3837100a4291911b7d90eb296acfff70784",["Text"]="-----------------------------------\n-- ID: 16249\n-- Elixir Tank\n-- When used, you will obtain one Elixir\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ELIXIR, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/elixir_vitae.lua"]={["Path"]="scripts/items/elixir_vitae.lua",["SHA256"]="1999c00c49d06c83aea7e84632951e90422400407991fb54cc1c9b058ad120ff",["Text"]="-----------------------------------\n-- ID: 5355\n-- Item: Elixir Vitae\n-- Item Effect: Instantly restores 3% of HP and MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    local mHP = target:getMaxHP()\n    local cHP = target:getHP()\n    local mMP = target:getMaxMP()\n    local cMP = target:getMP()\n\n    if mHP == cHP and mMP == cMP then\n        result = 56 -- Does not let player use item if their hp and mp are full\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    target:addHP((target:getMaxHP() / 100) * 3)\n    target:addMP((target:getMaxMP() / 100) * 3)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP_AND_MP)\nend\n\nreturn itemObject\n"},["scripts/items/elshena.lua"]={["Path"]="scripts/items/elshena.lua",["SHA256"]="bb176698bf0ecd9a9cad146cfea4e08d019f69a02d52c255bc33ca1cf3a568c5",["Text"]="-----------------------------------\n-- ID: 5886\n-- Item: elshena\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP +7% (cap 120)\n-- Increases rate of combat skill gains by 40%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 7)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 120)\n    effect:addMod(xi.mod.COMBAT_SKILLUP_RATE, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/elshimo_coconut.lua"]={["Path"]="scripts/items/elshimo_coconut.lua",["SHA256"]="ff4adaeda22e325fcb60e9746cb9c68fec5ddb52aa49da3a40634907fa885d72",["Text"]="-----------------------------------\n-- ID: 5187\n-- Item: elshimo_coconut\n-- Food Effect: 5Min, All Races\n-------------------