6814e28acdf78e9a47b35d15258c8b27",["Text"]="-----------------------------------\n-- ID: 15862\n-- Item: enthralling_brocade_obi\n-- Item Effect: CHR+10\n-- Duration: 3 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ENTHRALLING_BROCADE_OBI) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ENTHRALLING_BROCADE_OBI)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.ENTHRALLING_BROCADE_OBI) then\n        target:addStatusEffect(xi.effect.CHR_BOOST, { power = 10, duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.ENTHRALLING_BROCADE_OBI })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/ephramadian_throne.lua"]={["Path"]="scripts/items/ephramadian_throne.lua",["SHA256"]="44fea62bf8d9ab91662c009c6d8cecec8903fc6be2fa61f3c3d9231aefe0cbb5",["Text"]="-----------------------------------\n-- ID: 6409\n-- Item: Ephramadian Throne\n-- Item Effect: Grant Ephramadian throne key item\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nlocal keyItemId = xi.keyItem.EPHRAMADIAN_THRONE\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasKeyItem(keyItemId) then\n        return xi.msg.basic.ALREADY_HAVE_KEY_ITEM, 0, keyItemId\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addKeyItem(keyItemId)\n    target:messageBasic(xi.msg.basic.OBTAINED_KEY_ITEM, xi.item.EPHRAMADIAN_THRONE, keyItemId)\nend\n\nreturn itemObject\n"},["scripts/items/escritorio.lua"]={["Path"]="scripts/items/escritorio.lua",["SHA256"]="a90a34819c68215b50a26dbb2681f5d2a2c95cc95a1dfef3d10dc8e28d0d9588",["Text"]="-----------------------------------\n-- ID: 20953\n-- Escritorio\n-- Dispense: Cone Calamary\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.CONE_CALAMARY, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/ether.lua"]={["Path"]="scripts/items/ether.lua",["SHA256"]="ca2e9c7502a74b339999a599240f2adaabf11b23f3968ffc37a370abbdaac39e",["Text"]="-----------------------------------\n-- ID: 4128\n-- Item: Ether\n-- Item Effect: Restores 20 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(20 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/ether_+1.lua"]={["Path"]="scripts/items/ether_+1.lua",["SHA256"]="924de56c6670aff300d56a3b0f397d66218004fa03738f443fda6abad9f13b5b",["Text"]="-----------------------------------\n-- ID: 4129\n-- Item: Ether +1\n-- Item Effect: Restores 25 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(25 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/ether_+2.lua"]={["Path"]="scripts/items/ether_+2.lua",["SHA256"]="ecf5b7f763ea5eff4f216e40ad83e16c8ee2dd3566f1f8daccc81da62145dc1a",["Text"]="-----------------------------------\n-- ID: 4130\n-- Item: Ether +2\n-- Item Effect: Restores 30 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(30 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/ether_+3.lua"]={["Path"]="scripts/items/ether_+3.lua",["SHA256"]="de78fb24c0a4d565060951888bc1017b065670e3e790be56ff4a665b1b21da3c",["Text"]="-----------------------------------\n-- ID: 4131\n-- Item: Ether +3\n-- Item Effect: Restores 40 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(40 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/ether_tank.lua"]={["Path"]="scripts/items/ether_tank.lua",["SHA256"]="eecf87c9ebec0704e3213d19d1cd6c5a47bbc7448ef0addf62ec4a233f9904f9",["Text"]="-----------------------------------\n-- ID: 13682\n-- Ether Tank\n-- When used, you will obtain one Ether\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ETHER, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/evokers_gages.lua"]={["Path"]="scripts/items/evokers_gages.lua",["SHA256"]="f5dd08a1489e6fdedcd0c3ee228531968ebbdb138c734d58ec699dbea53a7147",["Text"]="-----------------------------------\n-- ID: 14960\n-- Evoker's Gages\n-- Pet mod via latent effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\nlocal listenerPrefix = 'PET_MOD_LATENT'\nlocal latentPetId = xi.petId.LEVIATHAN\nlocal latentMods =\n{\n    { xi.mod.ATT, 10 },\n}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemEquip  = function(user, item)\n    local listenerName = fmt('{}_{}', listenerPrefix, item:getID())\n    xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, true)\n\n    user:addListener('MAGIC_STATE_EXIT', listenerName, function(player, spell)\n        if spell:getSpellGroup() == xi.magic.spellGroup.SUMMONING then\n            xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, true)\n        end\n    end)\nend\n\nitemObject.onItemUnequip = function(user, item)\n    local listenerName = fmt('{}_{}', listenerPrefix, item:getID())\n    xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, false)\n\n    user:removeListener(listenerName)\nend\n\nreturn itemObject\n"},["scripts/items/excalibur_119.lua"]={["Path"]="scripts/items/excalibur_119.lua",["SHA256"]="c8de95d87c4e22e233643deac059e75e032f0827a0629d4024e471c91b5f6e54",["Text"]="-----------------------------------\n-- ID: 20645\n-- Item: Excalibur\n-- Additional effect: Slashing Damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance          = 7,\n        ignoreEnSpell   = true,\n        basePower       = math.floor(actor:getHP() / 4),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.SLASHING,\n        magicalElement  = xi.element.NONE,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/excalibur_119_ii.lua"]={["Path"]="scripts/items/excalibur_119_ii.lua",["SHA256"]="fd0364e21ce077dbc5f077001e5c24be2bc