--------\n-- ID: 19748\n-- Item: Excalibur\n-- Additional effect: Slashing Damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance          = 7,\n        ignoreEnSpell   = true,\n        basePower       = math.floor(actor:getHP() / 4),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.SLASHING,\n        magicalElement  = xi.element.NONE,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/excalibur_99_ii.lua"]={["Path"]="scripts/items/excalibur_99_ii.lua",["SHA256"]="2797569776c5ec36462064e0bc16558d82bf837cceb875e99e0c9fad790d7984",["Text"]="-----------------------------------\n-- ID: 19841\n-- Item: Excalibur\n-- Additional effect: Slashing Damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance          = 7,\n        ignoreEnSpell   = true,\n        basePower       = math.floor(actor:getHP() / 4),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.SLASHING,\n        magicalElement  = xi.element.NONE,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/expertise_ring.lua"]={["Path"]="scripts/items/expertise_ring.lua",["SHA256"]="cc77baf7703fdcbcdf805ccd906421b37483de80368c41094d37305e65c68836",["Text"]="-----------------------------------\n-- ID: 28569\n-- Item: Expertise Ring\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +75%\n-- Duration: 720 min\n-- Max bonus: 30000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 75\n    local duration  = 43200\n    local subpower  = 30000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/facility_ring.lua"]={["Path"]="scripts/items/facility_ring.lua",["SHA256"]="0aa1d6d3ae3cb3a72f62114eb6d56bc0a10007423a5ede0fd2daf388499d2c4a",["Text"]="-----------------------------------\n-- ID: 26165\n-- Item: facility ring\n-- Capacity point bonus\n-----------------------------------\n-- Bonus: +150%\n-- Duration: 720 min\n-- Max bonus: 30000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.COMMITMENT) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.COMMITMENT\n    local power     = 150\n    local duration  = 43200\n    local subpower  = 30000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/faerie_apple.lua"]={["Path"]="scripts/items/faerie_apple.lua",["SHA256"]="d21e891defdb7496a68805ab76ce708c27632f9bdcc2a869052e8e8e32d7600e",["Text"]="-----------------------------------\n-- ID: 4363\n-- Item: faerie_apple\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -4\n-- Intelligence 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -4)\n    effect:addMod(xi.mod.INT, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/fail-not.lua"]={["Path"]="scripts/items/fail-not.lua",["SHA256"]="c17aba0b12c2a5dbad3f6b66ee1fa8966791918c185ec57156114ddebdf2710d",["Text"]="-----------------------------------\n-- ID: 22117, 22131\n-- Item: Fail-Not\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getFreeSlotsCount() == 0 then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.CHRONO_ARROW, 99 } }) -- Chrono Arrows x99\nend\n\nreturn itemObject\n"},["scripts/items/falling_star.lua"]={["Path"]="scripts/items/falling_star.lua",["SHA256"]="6db258d86d04f19845385babaaab8318112d31dcc076c3c40d7403e1b1eea081",["Text"]="-----------------------------------\n-- ID: 5883\n-- Falling Star\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/fancy_gilet.lua"]={["Path"]="scripts/items/fancy_gilet.lua",["SHA256"]="21f6711054363d49c744e419e577a77deba4bb6467dc2055abf5799e2d3ff56a",["Text"]="-----------------------------------\n-- ID: 25774\n-- Fancy Gilet\n-- Dispenses Persikos Snow Cone\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.PERSIKOS_SNOW_CONE, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/fancy_top.lua"]={["Path"]="scripts/items/fancy_top.lua",["SHA256"]="b012aa87dd7b2af0e7a27d3e82379f33e295a0d57961c9c6a320b8d02ced8ef5",["Text"]="-----------------------------------\n-- ID: 25775\n-- Fancy Top\n-- Dispenses Persikos Snow Cone\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.PERSIKOS_SNOW_CONE, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/federation_earring.lua"]={["Path"]="scripts/items/federation_earring.lua",["SHA256"]="8afa8b6f934d077cee3a4db29b5055593a9f4dde47465edad452fbda8131e583",["Text"]="-----------------------------------\n-- ID: 16041\n-- Federation Earring\n-- Enchantment: \"Teleport\" (Windurst Waters)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.FEDERATION_EARRING, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/federation_signet_staff.lua"]={["Path"]="scripts/items/federation_signet_staff.lua",["SHA256"]="70735c065fcddc449c41c1a3901d97c4125ec334b18e6dfafcf4f7dc1cc59bbc",["Text"]="-----------------------------------\n-- ID: 17585\n-- Item: Federation Signet Staff\n-- Effect: Signet\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getNation() ~= xi.nation.WINDURST then\n        return xi.msg.basic.ITEM_CANNOT_USE_ON\n    end\n\n    -- If target's current region is not a conquest region or not a nation city involved with conquest\n    if target:getCurrentRegion() > xi.region.JEUNO then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    -- Can only use on targets within party or self\n    if target:getID() ~= caster:getID() then\n        if\n            caster:getPartyLeader() == nil or\n            target:getPartyLeader():getID() ~= caster:getPartyLeader():getID()\n        then\n            return xi.msg.basic.ITEM_CANNOT_USE_ON\n        end\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:delStatusEffectsByFlag(xi.effectFlag.INFLUENCE, true)\n    target:addStatusEffect(xi.effect.SIGNET, { duration = 18000, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/federation_stables_scarf.lua"]={["Path"]="scripts/items/federation_stables_scarf.lua",["SHA256"]="8b534f64e5d06acfb9631ce41ce10589ed30ba3fb6b46befe1f6f68278e09348",["Text"]="-----------------------------------\n-- ID: 13181\n-- Item: Federation Stables Scarf\n-- Teleports to Chocobo Stables (Windurst)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.WINDURST_WOODS) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.CHOCO_WINDURST, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/felicifruit.lua"]={["Path"]="scripts/items/felicifruit.lua",["SHA256"]="41cbc4a0b948428d908ee16f7d5128e8b4dc61998530ab049d29068e5e2aff01",["Text"]="-----------------------------------\n-- ID: 5964\n-- Item: Felicifruit\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -7\n-- Intelligence 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -7)\n    effect:addMod(xi.mod.INT, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/fenrirs_crown.lua"]={["Path"]="scripts/items/fenrirs_crown.lua",["SHA256"]="d336c696585e9b9d92295f9d33513b4ab334a12d2908c785c6f5d30f441a6a5e",["Text"]="-----------------------------------\n-- ID: 11496\n-- Fenrir's Crown\n-- Pet mod via latent effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\nlocal listenerPrefix = 'PET_MOD_LATENT'\nlocal latentPetId = xi.petId.FENRIR\nlocal latentMods =\n{\n    { xi.mod.ACC, 5 },\n}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemEquip  = function(user, item)\n    local listenerName = fmt('{}_{}', listenerPrefix, item:getID())\n    xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, true)\n\n    user:addListener('MAGIC_STATE_EXIT', listenerName, function(player, spell)\n        if spell:getSpellGroup() == xi.magic.spellGroup.SUMMONING then\n            xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, true)\n        end\n    end)\nend\n\nitemObject.onItemUnequip = function(user, item)\n    local listenerName = fmt('{}_{}', listenerPrefix, item:getID())\n    xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, false)\n\n    user:removeListener(listenerName)\nend\n\nreturn itemObject\n"},["scripts/items/fervor_ring.lua"]={["Path"]="scripts/items/fervor_ring.lua",["SHA256"]="c9a5c03103a8735043dd13a8b394a3eceec1531002b57b8f28dc2945f9e4a950",["Text"]="-----------------------------------\n-- ID: 11675\n-- Fervor Ring\n-- Pet mod via latent effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\nlocal listenerPrefix = 'PET_MOD_LATENT'\nlocal latentPetId = xi.petId.IFRIT\nlocal latentMods =\n{\n    { xi.mod.MATT, 2 },\n}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemEquip  = function(user, item)\n    local listenerName = fmt('{}_{}', listenerPrefix, item:getID())\n    xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, true)\n\n    user:addListener('MAGIC_STATE_EXIT', listenerName, function(player, spell)\n        if spell:getSpellGroup() == xi.magic.spellGroup.SUMMONING then\n            xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, true)\n        end\n    end)\nend\n\nitemObject.onItemUnequip = function(user, item)\n    local listenerName = fmt('{}_{}', listenerPrefix, item:getID())\n    xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, false)\n\n    user:removeListener(listenerName)\nend\n\nreturn itemObject\n"},["scripts/items/festive_fan.lua"]={["Path"]="scripts/items/festive_fan.lua",["SHA256"]="1c38cdc8577fd2a18626fc59beb7f41bcb8faffe67ad6653bbd25492ad6ef92e",["Text"]="-----------------------------------\n-- ID: 4251\n-- Festive Fan\n-- A paper fan appears in the user's left hand\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/fire_arrow.lua"]={["Path"]="scripts/items/fire_arrow.lua",["SHA256"]="bd23adf8fa4b9705012fc7bded2d9fcfe68fe839824f30de2201ed9a6d91b648",["Text"]="-----------------------------------\n-- ID: 17322\n-- Item: Fire Arrow\n-- Additional effect: Fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    -- Unconfirmed power.\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = math.random(7, 10),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.FIRE,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/fire_bracers.lua"]={["Path"]="scripts/items/fire_bracers.lua",["SHA256"]="ca303de2a6e0a580dea7eabe715812a801fe8f5421a0ce7f9f6763396308adc9",["Text"]="-----------------------------------\n-- ID: 14991\n-- Fire Bracers\n--  Enchantment: \"Enfire\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local fakeSpell = GetSpell(xi.magic.spell.ENFIRE)\n    xi.spells.enhancing.useEnhancingSpell(target, target, fakeSpell)\nend\n\nreturn itemObject\n"},["scripts/items/fire_card_case.lua"]={["Path"]="scripts/items/fire_card_case.lua",["SHA256"]="7c9cedf18022d33ba62a317c0d9121f11c9aa1494d46be86ec8ae426b7c5487e",["Text"]="-----------------------------------\n-- ID: 5402\n-- Fire Card Case\n-- When used, you will obtain one stack of Fire Cards\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FIRE_CARD, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/fire_cluster.lua"]={["Path"]="scripts/items/fire_cluster.lua",["SHA256"]="4d859408c6d7dc89f60c1f09018e0eb0064f7f77cc5a26ca79a06f6fae6932e6",["Text"]="-----------------------------------\n-- ID: 4104\n-- Fire Cluster\n-- Turn into a stack of fire crystals\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FIRE_CRYSTAL, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/fire_feather.lua"]={["Path"]="scripts/items/fire_feather.lua",["SHA256"]="a15844d4ba78f418b9abdd6e01b3a17562d3c2edbf010c05d4752274d61a30c4",["Text"]="-----------------------------------\n-- ID: 5256\n-- Item: Fire Feather\n-- Status Effect: Enfire\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.ENFIRE, { power = 10, duration = 180, origin = user }) -- This is a guess, no potency or duration info is known\nend\n\nreturn itemObject\n"},["scripts/items/fire_spirit_pact.lua"]={["Path"]="scripts/items/fire_spirit_pact.lua",["SHA256"]="5b790380150cacd11a788bddbbd0f9910bb36b31d3ee9f198156b3e90764b807",["Text"]="-----------------------------------\n-- ID: 4896\n-- Fire Spirit Pact\n-- Teaches the summoning magicFire Spirit\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.FIRE_SPIRIT)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.FIRE_SPIRIT)\nend\n\nreturn itemObject\n"},["scripts/items/fire_staff.lua"]={["Path"]="scripts/items/fire_staff.lua",["SHA256"]="99276ba0924b5caa50f251a9ed4335c174127df3080b407c18066e58f514be43",["Text"]="-----------------------------------\n-- ID: 17545\n-- Item: Fire Staff\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 15, -- guessed\n        basePower      = math.randomInt(12, 16),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/fire_sword.lua"]={["Path"]="scripts/items/fire_sword.lua",["SHA256"]="69c304cf09d7dd286e8a6aa1e398d869230f6027fc3a3753a0a3b8da94b6f89a",["Text"]="-----------------------------------\n-- ID: 16543\n-- Item: Fire Sword\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"}};
